# ==============================================================================
# As a sender, strange characters and combinations are very suspicious.
# Here we check the sender for crazy stuff.
#
# ------------------------------------------------------------------------------
# Language: -
# Weight:   6.0
# ==============================================================================

# Special
# ==============================================================================
# -> Theses RegEx might be constructed easier and better

# Sample: "Melissa, 20"
/[a-z]{3,15},.?\d{2}/i
# Sample: "Melissa (21)"
/[a-z]{3,15}.?\(\d{2}\)/i

# Sample: "(1)"
/\(\d\)/i

# Sample: "[iPad Pro"
#         "| Netflix Inc |"
#         "_ Congrats _"
#         "- EMURA -"
#         "* FedEx *"

# "[" and "]" removed, because they are used
/[\|\-\*_!#][a-z0-9\s]{3,15}[\|\-\*_!#]$/i

#
/\d{2,3}.?(dollars?|euro?|gbp|usd|€|\$|£)/i

# Sample: "25/12/2024 Nachrichten"
/\d{2}\/\d{2}\/\d{4}/i

# Just numbers like an email address, but without the domain part
/\d{4,15}@/i

# Multiple special characters and silly combinations
# ------------------------------------------------------------------------------
# -> Theses RegEx might be constructed easier and better
/\?\?/i

/__/i

#/--/i
/!!!/i

# Just three dots
/\.\.\.$/i

# Just a number
/^\d{4,15}$/i

# Sample: --d--
/--[a-z0-9]--/i

# Sample: Abteilung .""
# To many F/P
#/\.$/i

# Sample: HeRMeS**-
/\*\*-/i

# Sample: _Tractor*Supply
/_[a-z0-9]{3,15}\*/i

# Sample: Lidl Kundendienst//
/\/\/$/i

# Strange patttern
/\*\/\//i

# Sample: +KAi++7v+
/\+.{3,10}\+\+/i

# Sample: DomainFactory@ | ( NoReply )
/@ \| \(/i

# Emoji
# ------------------------------------------------------------------------------
/✅/
/🔔/
/💯/
/₿/
/🏛️/
/✔/

# Special characters 
# ------------------------------------------------------------------------------
/(™|®|©)$/i



/】.{3,30}【/i
/【.{3,30}】/i

# Placeholders
# ------------------------------------------------------------------------------
/%(last|user)_name%/i

# Obfuscation patterns
# ------------------------------------------------------------------------------
# Detect standalone bidirectional control characters used to spoof visual order
/[‮‬‭‪‫⁦⁧⁨⁩]/i

# Detect text wrapped in RLO/PDF markers (U+202E ... U+202C), a common masking trick
/‮.{0,80}‬/i

# Detect repeated invisible Unicode separator characters used as letter gaps or placeholders
/[​‌‍﻿‏⁠]{4,}/i

# Amazon with hidden Unicode separators like A‌m⁠a‌z​on\.co\.jp
# ------------------------------------------------------------------------------
/a(?:[​‌‍﻿‏⁠]+[​‌‍﻿‏⁠]*|)m(?:[​‌‍﻿‏⁠]+[​‌‍﻿‏⁠]*|)a(?:[​‌‍﻿‏⁠]+[​‌‍﻿‏⁠]*|)z(?:[​‌‍﻿‏⁠]+[​‌‍﻿‏⁠]*|)o[​‌‍﻿‏⁠]+[​‌‍﻿‏⁠]*n(?:[​‌‍﻿‏⁠]*\.[​‌‍﻿‏⁠]*c(?:[​‌‍﻿‏⁠]+[​‌‍﻿‏⁠]*|)o[​‌‍﻿‏⁠]*\.[​‌‍﻿‏⁠]*j[​‌‍﻿‏⁠]*p)?/i

# Apple with hidden Unicode separators like A‌p⁠p‌l​e
# ------------------------------------------------------------------------------
/a(?:[​‌‍﻿‏⁠]+[​‌‍﻿‏⁠]*|)p(?:[​‌‍﻿‏⁠]+[​‌‍﻿‏⁠]*|)p(?:[​‌‍﻿‏⁠]+[​‌‍﻿‏⁠]*|)l[​‌‍﻿‏⁠]+[​‌‍﻿‏⁠]*e/i